#include "win32_gui_prefs.h"
#define requested_width width
#define requested_height height
#define requested_colour_depth colour_depth
#define window_size_type geometry_type
#define RDESKTOP_AUDIO_OFF RDESKTOP_AUDIO_DISABLED
#ifdef _WIN32
#define PREFS_KEY "Software\\rdesktop\\Win32 GUI"
#define PROFILE_VERSION 1
typedef struct { DWORD version; char server[256],username[256],domain[256]; uint16 port; uint32 width,height; int window_mode,depth,protocol; char keymap[PATH_MAX]; RD_BOOL numlock_sync,clipboard_enabled; int audio_mode; uint32 performance_flags; RD_BOOL send_motion,compression,bitmap_cache,console_session,retry_on_network_error; char tls_version[4],hostname[16],codepage[16],shell[256],directory[256],title[64]; } WIN32_GUI_PROFILE;
static RD_BOOL read_profile(HKEY k,int i,WIN32_GUI_PROFILE*p){char n[16];DWORD t=REG_BINARY,s=sizeof(*p);sprintf(n,"Profile%d",i);memset(p,0,sizeof(*p));return RegQueryValueExA(k,n,NULL,&t,(BYTE*)p,&s)==ERROR_SUCCESS&&t==REG_BINARY&&s==sizeof(*p)&&p->version==PROFILE_VERSION;}
static void write_profile(HKEY k,int i,const WIN32_GUI_PROFILE*p){char n[16];sprintf(n,"Profile%d",i);RegSetValueExA(k,n,0,REG_BINARY,(const BYTE*)p,sizeof(*p));}
static void from_config(WIN32_GUI_PROFILE*p,const RDESKTOP_CONFIG*c){memset(p,0,sizeof(*p));p->version=PROFILE_VERSION;STRNCPY(p->server,c->server,sizeof(p->server));STRNCPY(p->username,c->username,sizeof(p->username));STRNCPY(p->domain,c->domain,sizeof(p->domain));p->port=c->port;p->width=c->requested_width;p->height=c->requested_height;p->window_mode=c->window_mode;p->depth=c->requested_colour_depth;p->protocol=c->rdp_version;STRNCPY(p->keymap,c->keymap,sizeof(p->keymap));p->numlock_sync=c->numlock_sync;p->clipboard_enabled=c->clipboard_enabled;p->audio_mode=c->audio_mode;p->performance_flags=c->performance_flags;p->send_motion=c->send_motion;p->compression=c->compression;p->bitmap_cache=c->bitmap_cache;p->console_session=c->console_session;p->retry_on_network_error=c->retry_on_network_error;STRNCPY(p->tls_version,c->tls_version,sizeof(p->tls_version));STRNCPY(p->hostname,c->hostname,sizeof(p->hostname));STRNCPY(p->codepage,c->codepage,sizeof(p->codepage));STRNCPY(p->shell,c->shell,sizeof(p->shell));STRNCPY(p->directory,c->directory,sizeof(p->directory));STRNCPY(p->title,c->title,sizeof(p->title));}
static void to_config(const WIN32_GUI_PROFILE*p,RDESKTOP_CONFIG*c){STRNCPY(c->server,p->server,sizeof(c->server));STRNCPY(c->username,p->username,sizeof(c->username));STRNCPY(c->domain,p->domain,sizeof(c->domain));c->password[0]=0;c->port=p->port;c->requested_width=p->width;c->requested_height=p->height;c->window_mode=(RDESKTOP_WINDOW_MODE)p->window_mode;c->fullscreen=c->window_mode==RDESKTOP_WINDOW_FULLSCREEN;c->window_size_type=c->fullscreen?Fullscreen:Fixed;c->requested_colour_depth=p->depth;c->rdp_version=(RDP_VERSION)p->protocol;STRNCPY(c->keymap,p->keymap,sizeof(c->keymap));c->numlock_sync=p->numlock_sync;c->clipboard_enabled=p->clipboard_enabled;c->audio_mode=(RDESKTOP_AUDIO_MODE)p->audio_mode;c->performance_flags=p->performance_flags;c->send_motion=p->send_motion;c->compression=p->compression;c->bitmap_cache=p->bitmap_cache;c->console_session=p->console_session;c->retry_on_network_error=p->retry_on_network_error;STRNCPY(c->tls_version,p->tls_version,sizeof(c->tls_version));STRNCPY(c->hostname,p->hostname,sizeof(c->hostname));STRNCPY(c->codepage,p->codepage,sizeof(c->codepage));STRNCPY(c->shell,p->shell,sizeof(c->shell));STRNCPY(c->directory,p->directory,sizeof(c->directory));STRNCPY(c->title,p->title,sizeof(c->title));}
void win32_gui_prefs_load_servers(char s[WIN32_GUI_MRU_COUNT][256]){HKEY k;int i;memset(s,0,WIN32_GUI_MRU_COUNT*256);if(RegOpenKeyExA(HKEY_CURRENT_USER,PREFS_KEY,0,KEY_QUERY_VALUE,&k)!=ERROR_SUCCESS)return;for(i=0;i<WIN32_GUI_MRU_COUNT;i++){char n[16];DWORD t=REG_SZ,z=256;sprintf(n,"Server%d",i);RegQueryValueExA(k,n,NULL,&t,(BYTE*)s[i],&z);s[i][255]=0;}RegCloseKey(k);}
RD_BOOL win32_gui_prefs_load_profile(const char*s,RDESKTOP_CONFIG*c){HKEY k;int i;WIN32_GUI_PROFILE p;RD_BOOL f=False;if(!s||!*s||RegOpenKeyExA(HKEY_CURRENT_USER,PREFS_KEY,0,KEY_QUERY_VALUE,&k)!=ERROR_SUCCESS)return False;for(i=0;i<WIN32_GUI_MRU_COUNT;i++)if(read_profile(k,i,&p)&&!_stricmp(p.server,s)){rdesktop_config_clear_password(c);to_config(&p,c);f=True;break;}RegCloseKey(k);return f;}
void win32_gui_prefs_remember_profile(const RDESKTOP_CONFIG*c){WIN32_GUI_PROFILE old[5],list[5];HKEY k;DWORD d;int i,n=1;if(!c||!c->server[0])return;memset(old,0,sizeof(old));memset(list,0,sizeof(list));from_config(&list[0],c);if(RegCreateKeyExA(HKEY_CURRENT_USER,PREFS_KEY,0,NULL,0,KEY_QUERY_VALUE|KEY_SET_VALUE,NULL,&k,&d)!=ERROR_SUCCESS)return;for(i=0;i<5;i++)read_profile(k,i,&old[i]);for(i=0;i<5&&n<5;i++)if(old[i].version&&_stricmp(old[i].server,c->server))list[n++]=old[i];for(i=0;i<5;i++){char q[16];sprintf(q,"Server%d",i);if(list[i].version){write_profile(k,i,&list[i]);RegSetValueExA(k,q,0,REG_SZ,(BYTE*)list[i].server,(DWORD)strlen(list[i].server)+1);}else{RegDeleteValueA(k,q);sprintf(q,"Profile%d",i);RegDeleteValueA(k,q);}}RegCloseKey(k);}
void win32_gui_prefs_remember_server(const char*s){RDESKTOP_CONFIG c;if(!s||!*s)return;rdesktop_config_init(&c);STRNCPY(c.server,s,sizeof(c.server));win32_gui_prefs_remember_profile(&c);}
void win32_gui_prefs_load_global(char*l,size_t z,RD_BOOL*e){HKEY k;DWORD t=REG_SZ,s=(DWORD)z,d=0,dz=sizeof(d);STRNCPY(l,"en-US",z);*e=False;if(RegOpenKeyExA(HKEY_CURRENT_USER,PREFS_KEY,0,KEY_QUERY_VALUE,&k)!=ERROR_SUCCESS)return;RegQueryValueExA(k,"Language",NULL,&t,(BYTE*)l,&s);l[z-1]=0;if(RegQueryValueExA(k,"Expanded",NULL,&t,(BYTE*)&d,&dz)==ERROR_SUCCESS)*e=d?True:False;RegCloseKey(k);}
void win32_gui_prefs_save_global(const char*l,RD_BOOL e){HKEY k;DWORD d,v=e?1:0;if(RegCreateKeyExA(HKEY_CURRENT_USER,PREFS_KEY,0,NULL,0,KEY_SET_VALUE,NULL,&k,&d)!=ERROR_SUCCESS)return;RegSetValueExA(k,"Language",0,REG_SZ,(const BYTE*)l,(DWORD)strlen(l)+1);RegSetValueExA(k,"Expanded",0,REG_DWORD,(const BYTE*)&v,sizeof(v));RegCloseKey(k);}
#endif
